374	// validateLoaded 对解码后的状态做基本不变量检查，违背即视为损坏。
375	func validateLoaded(fd *fileData) error {
376		switch {
377		case fd.Version != int(fileVersion):
378			return fmt.Errorf("%w: version %d in payload", ErrUnsupportedVersion, fd.Version)
379		case len(fd.Trajectory) == 0:
380			return fmt.Errorf("%w: empty trajectory", ErrCorrupt)
381		}
382		if err := validateConfig(fd.Config); err != nil {
383			// 配置不合法不可能由本版本写出。
384			return fmt.Errorf("%w: %v", ErrCorrupt, err)
385		}
386		// 保存的整条轨迹必须满足与导入时相同的时间规则：从初始位姿起
387		// 时间严格递增，且相邻位姿的真实间隔不超过 MaxInterval（恰好
388		// 等于上限合法）。任何一处相等、倒退或超限都使按时间查询失去
389		// 可靠的先后依据，整份文件按损坏拒绝。间隔按真实差值判断：前
390		// 一时间接近 math.MinInt64 而后一时间为非负时，有符号减法会
391		// 溢出回绕成负数，把超限的巨大缺口放过去；此处已保证递增，真
392		// 实差值落在 [1, 2^64-1]，用无符号减法取精确的数学差值再与上
393		// 限比较（MaxInterval 已校验为正）。
394		for i := 1; i < len(fd.Trajectory); i++ {
395			prev, cur := fd.Trajectory[i-1].Time, fd.Trajectory[i].Time
396			if cur <= prev {
397				return fmt.Errorf("%w: trajectory time at pose %d is not strictly increasing", ErrCorrupt, i)
398			}
399			if uint64(cur)-uint64(prev) > uint64(fd.Config.MaxInterval) {
400				return fmt.Errorf("%w: trajectory interval between poses %d and %d exceeds max interval", ErrCorrupt, i-1, i)
401			}
402		}
403		// 新格式的逐帧依据必须与轨迹（除初始位姿外）一一对应；旧文件缺省
404		// 该字段（解码为 nil），数量为 0。
405		if len(fd.Sources) != 0 && len(fd.Sources) != len(fd.Trajectory)-1 {
406			return fmt.Errorf("%w: frame sources length %d for %d frames", ErrCorrupt, len(fd.Sources), len(fd.Trajectory)-1)
407		}
408		seenIDs := make(map[string]struct{}, len(fd.Landmarks))
409		for _, lm := range fd.Landmarks {
410			if lm.ID == "" {
411				return fmt.Errorf("%w: invalid landmark record", ErrCorrupt)
412			}
413			if _, dup := seenIDs[lm.ID]; dup {
414				return fmt.Errorf("%w: duplicate landmark %s", ErrCorrupt, lm.ID)
415			}
416			seenIDs[lm.ID] = struct{}{}
417			if len(lm.Occurrences) == 0 {
418				// 兼容旧布局：平铺字段表示第 1 次出现。
419				if lm.Count < 1 || !isFinite(lm.X) || !isFinite(lm.Y) {
420					return fmt.Errorf("%w: invalid landmark record", ErrCorrupt)
421				}
422				if lm.LegacyCount < 0 || lm.LegacyCount > lm.Count {
423					return fmt.Errorf("%w: invalid legacy count for landmark %s", ErrCorrupt, lm.ID)
424				}
425				if lm.LegacyCount > 0 && (!isFinite(lm.LegacyMX) || !isFinite(lm.LegacyMY)) {
426					return fmt.Errorf("%w: invalid legacy mean for landmark %s", ErrCorrupt, lm.ID)
427				}
428				continue
429			}
430			activeCount := 0
431			for i, oj := range lm.Occurrences {
432				if oj.Number != i+1 || oj.Count < 1 || !isFinite(oj.X) || !isFinite(oj.Y) {
433					return fmt.Errorf("%w: invalid occurrence for landmark %s", ErrCorrupt, lm.ID)
434				}
435				if oj.LegacyCount < 0 || oj.LegacyCount > oj.Count {
436					return fmt.Errorf("%w: invalid legacy count for landmark %s occurrence %d", ErrCorrupt, lm.ID, oj.Number)
437				}
438				if oj.LegacyCount > 0 && (!isFinite(oj.LegacyMX) || !isFinite(oj.LegacyMY)) {
439					return fmt.Errorf("%w: invalid legacy mean for landmark %s occurrence %d", ErrCorrupt, lm.ID, oj.Number)
440				}
441				if oj.Active {
442					activeCount++
443					if i != len(lm.Occurrences)-1 {
444						return fmt.Errorf("%w: active occurrence %d of landmark %s is not the latest", ErrCorrupt, oj.Number, lm.ID)
445					}
446				} else if oj.InvalidReason == "" {
447					return fmt.Errorf("%w: invalidated occurrence %d of landmark %s lacks reason", ErrCorrupt, oj.Number, lm.ID)
448				}
449				// 出现编号即先后次序，各次出现接纳观测的时间范围必须与之
450				// 相容，否则同一观测可能同时属于两次出现（归属校验只确认能
451				// 归入某一次，不排除同时归入两次）。已失效且首次观测时间
452				// 已知的出现，首次观测不能晚于失效；下一次出现的首次观测
453				// 必须严格晚于上一次的失效时间——首次观测与失效两个端点都
454				// 接纳所在时刻的观测，相等即重叠。第 2 次及以后的出现必定
455				// 在上一次失效之后由本包创建，首次观测时间必须已知；只有
456				// 旧文件的第 1 次出现允许未知（无下界，不把零当作起点）。
457				// 这些检查针对保存的出现记录本身，与重叠范围内当前是否有
458				// 观测无关。
459				if !oj.Active && oj.HasFirstSeen && oj.FirstSeenTime > oj.InvalidTime {
460					return fmt.Errorf("%w: occurrence %d of landmark %s first seen at %d after invalidation at %d", ErrCorrupt, oj.Number, lm.ID, oj.FirstSeenTime, oj.InvalidTime)
461				}
462				if i > 0 {
463					if !oj.HasFirstSeen {
464						return fmt.Errorf("%w: occurrence %d of landmark %s lacks first seen time", ErrCorrupt, oj.Number, lm.ID)
465					}
466					// 上一次出现必已失效（仍有效且非最后一次已在上面拒绝）。
467					if prev := lm.Occurrences[i-1]; oj.FirstSeenTime <= prev.InvalidTime {
468						return fmt.Errorf("%w: occurrence %d of landmark %s starts at %d before previous invalidation at %d", ErrCorrupt, oj.Number, lm.ID, oj.FirstSeenTime, prev.InvalidTime)
469					}
470				}
471			}
472			if activeCount > 1 {
473				return fmt.Errorf("%w: multiple active occurrences for landmark %s", ErrCorrupt, lm.ID)
474			}
475		}
476		// 观测重放器：各路标历次出现的时间边界（归属规则见 occurrence.go）
477		// 与逐条重建位置的流程（见 replay.go）和回环校正共享同一实现；来源
478		// 帧的归属核对、次数/首次时间统计、位置核对与校正记录路标列表核对
479		// 都经由它进行。旧文件缺省 sources（解码为 nil）时不构建，这些核对
480		// 都不进行。
481		var replay *observationReplay
482		// cumBySrc 仅在逐帧依据存在时构建：键为来源下标 k（对应帧
483		// trajectory[k+1]），值为从首帧到该帧（两端含）为止按时间边界归属
484		// 各次出现的累计已接纳观测条数快照，只为某条校正记录结束帧所在的下
485		// 标保存。次数核对按各记录自己的结束帧取对应快照，再加该出现保存的
486		// 固定旧贡献（legacyByKey）。
487		var cumBySrc map[int]map[occurrenceKey]int
488		var legacyByKey map[occurrenceKey]int
489		if len(fd.Sources) != 0 {
490			replay = newObservationReplay(fd.Config.MergeDistance)
491			for _, lm := range fd.Landmarks {
492				replay.track(lm.ID, occurrenceWindowsOf(lm))
493			}
494			// 预登记各校正记录结束帧对应的来源下标，只为这些下标保留累计快
495			// 照，避免对每一帧都复制整份计数。
496			cumBySrc = make(map[int]map[occurrenceKey]int, len(fd.Corrections))
497			for _, cr := range fd.Corrections {
498				for j := 1; j < len(fd.Trajectory); j++ {
499					if fd.Trajectory[j].Time == cr.EndTime {
500						cumBySrc[j-1] = nil
501						break
502					}
503				}
504			}
505		}
506		// 校验每条带逐帧依据的观测来源：观测路标必须存在，且所在帧时间必须
507		// 落入该路标某一次出现的时间边界（共享规则见 occurrence.go）。旧出现
508		// 已失效不代表其历史观测无效；同一标识两次出现之间（如 200 失效、
509		// 300 再现时的 250 帧）的观测没有归属，按损坏拒绝。null 帧来自缺少
510		// 逐帧依据的旧地图，其观测不在这里（也无法）核验；旧版平铺路标视为
511		// 一次无边界的有效出现，因此旧地图后来追加的来源帧仍按此规则检查。
512		if len(fd.Sources) != 0 {
513			// 归属校验的同时按（路标，出现编号）统计来源观测条数：每条观测
514			// 各算一次，同帧重复观测同一标识不去重，空观测帧不计。null 帧
515			// 缺少逐帧依据，其贡献已固定在出现的旧观测计数中，不在此统计，
516			// 也不能按帧数猜测。同时记录归属各次出现的最早来源观测帧时间，
517			// 供下方首次观测时间核对使用。
518			tallies := make(map[string]map[int]int, len(fd.Landmarks))
519			firstObs := make(map[string]map[int]int64, len(fd.Landmarks))
520			for k, src := range fd.Sources {
521				if src == nil {
522					continue // 旧地图帧：无逐帧依据，不要求补齐归属
523				}
524				t := fd.Trajectory[k+1].Time
525				for _, ob := range src.Observations {
526					num, known := replay.occurrenceOf(ob.ID, t)
527					if !known {
528						return fmt.Errorf("%w: observation of unknown landmark %s at frame time %d", ErrCorrupt, ob.ID, t)
529					}
530					if num == 0 {
531						return fmt.Errorf("%w: observation of landmark %s at frame time %d belongs to no occurrence", ErrCorrupt, ob.ID, t)
532					}
533					c := tallies[ob.ID]
534					if c == nil {
535						c = make(map[int]int, 1)
536						tallies[ob.ID] = c
537					}
538					c[num]++
539					f := firstObs[ob.ID]
540					if f == nil {
541						f = make(map[int]int64, 1)
542						firstObs[ob.ID] = f
543					}
544					if cur, ok := f[num]; !ok || t < cur {
545						f[num] = t
546					}
547				}
548			}
549			// 每次出现记录的观测次数必须等于归属该次出现的来源观测条数加上
550			// 该次出现已保存的旧观测贡献：偏多或偏少都是文件损坏。各次出现
551			// 分别核对，不能用另一次出现的观测补足；已失效的旧出现同样核对，
552			// 不因它不再参与区域查询而跳过。回环校正只改位置不改已接受观测
553			// 次数，正常校正后保存的文件仍满足此不变量。
554			for _, lm := range fd.Landmarks {
555				if len(lm.Occurrences) == 0 {
556					// 旧版平铺路标即第 1 次出现。
557					if got := tallies[lm.ID][1] + lm.LegacyCount; got != lm.Count {
558						return fmt.Errorf("%w: landmark %s records %d observations but sources and legacy contributions account for %d", ErrCorrupt, lm.ID, lm.Count, got)
559					}
560					continue
561				}
562				for _, oj := range lm.Occurrences {
563					if got := tallies[lm.ID][oj.Number] + oj.LegacyCount; got != oj.Count {
564						return fmt.Errorf("%w: landmark %s occurrence %d records %d observations but sources and legacy contributions account for %d", ErrCorrupt, lm.ID, oj.Number, oj.Count, got)
565					}
566				}
567			}
568	
569			// 首次观测时间核对：首次观测时间已知、且全部观测都具有逐帧来源
570			// （无固定旧贡献）的每次出现，记录的首次时间必须准确等于实际归属
571			// 该次出现的最早来源观测帧时间。写早或写晚都是损坏：错误时间即使
572			// 恰好命中某个已保存的帧，只要该帧没有观测这一路标也不能接受；
573			// 错误时间没有对应帧同样拒绝。各次出现分别核对——已失效的旧出现
574			// 与失效后再现的新出现各自依据自己的观测判断，不能互相代替；后续
575			// 帧继续观测或同帧重复观测都不改变首次时间。时间为零或负数是合法
576			// 帧时间，按实际值比较，不把零当作时间未知。旧文件第 1 次出现缺
577			// 少旧观测依据、首次时间未知（HasFirstSeen 为假），或仍含固定旧
578			// 贡献时，其最早观测无从核对，保留旧地图的既有打开规则；但旧路标
579			// 失效后新导入产生的出现依据完整、首次时间已知，不因同一文件存在
580			// 旧历史而跳过核对。回环校正只改位姿与位置，不改观测帧时间，已正
581			// 确保存的校正地图仍满足此不变量。
582			for _, lm := range fd.Landmarks {
583				for _, oj := range lm.Occurrences {
584					if !oj.HasFirstSeen || oj.LegacyCount > 0 {
585						continue
586					}
587					// 次数核对已保证 Count-LegacyCount 条来源观测存在，最早
588					// 帧时间必然已记录；缺失本身即矛盾。
589					first, ok := firstObs[lm.ID][oj.Number]
590					if !ok || first != oj.FirstSeenTime {
591						return fmt.Errorf("%w: landmark %s occurrence %d records first seen time %d but its earliest sourced observation is at frame time %d", ErrCorrupt, lm.ID, oj.Number, oj.FirstSeenTime, first)
592					}
593				}
594			}
595	
596			// 位置核对：次数相符只说明观测“条数”对得上，还必须核对保存的路标
597			// 位置确实是这些观测依据当前保存位姿重放后的等权平均。每条来源观测
598			// 按所在帧当前保存的位姿转换到地图坐标，按帧时间升序、同帧按输入
599			// 次序，归入各自出现分别重放；同帧对同一标识的多条观测各自参与，
600			// 空观测帧不增加贡献。归组、固定旧贡献起点与逐条重建全部经由与
601			// 回环校正共享的重放器（见 replay.go，单条接纳规则见 aggregate.go），
602			// 旧文件固定旧贡献（LegacyCount 次平均）作为聚合起点——不能当成零，
603			// 也不能用缺少依据的帧数代替。回环校正后保存的文件按当前轨迹重放
604			// 即得到当前位置，不要求等于校正记录里的历史快照；各次出现分别核
605			// 对，已失效的出现同样核对。合并距离只是导入/校正时的接纳门槛，不
606			// 是保存位置偏差的容许范围：重放中出现非有限结果或距离冲突，或最
607			// 终平均位置与保存位置不完全一致，都按损坏拒绝。纯旧文件没有
608			// sources、null 旧帧没有依据，均不重放。
609			for _, lm := range fd.Landmarks {
610				if len(lm.Occurrences) == 0 {
611					// 旧版平铺路标即第 1 次出现。
612					replay.seed(lm.ID, 1, lm.LegacyCount, lm.LegacyMX, lm.LegacyMY)
613					continue
614				}
615				for _, oj := range lm.Occurrences {
616					replay.seed(lm.ID, oj.Number, oj.LegacyCount, oj.LegacyMX, oj.LegacyMY)
617				}
618			}
619			frames := make([]replayFrame, 0, len(fd.Sources))
620			for k, src := range fd.Sources {
621				if src == nil {
622					continue // 旧地图帧：无逐帧依据，其贡献固定在旧贡献起点中
623				}
624				pose := fd.Trajectory[k+1]
625				frames = append(frames, replayFrame{time: pose.Time, pose: pose, observations: src.Observations})
626			}
627			if rej := replay.replay(frames); rej != nil {
628				switch rej.reason {
629				case replayNonFinite:
630					return fmt.Errorf("%w: replayed observation of landmark %s occurrence %d at frame time %d is non-finite", ErrCorrupt, rej.id, rej.num, rej.time)
631				case replayConflict:
632					return fmt.Errorf("%w: replayed observation of landmark %s occurrence %d at frame time %d violates merge distance", ErrCorrupt, rej.id, rej.num, rej.time)
633				default:
634					// 归属（存在性与时间边界）已在上面校验，不会无法归组。
635					return fmt.Errorf("%w: observation of landmark %s at frame time %d belongs to no occurrence", ErrCorrupt, rej.id, rej.time)
636				}
637			}
638			checkPosition := func(id string, num int, x, y float64) error {
639				a := replay.agg(id, num)
640				// 次数核对已保证 a.count 与记录次数一致（含旧贡献起点），这里只
641				// 核对位置：保存位置必须与按依据重放出的等权平均完全一致。
642				if a.x != x || a.y != y {
643					return fmt.Errorf("%w: landmark %s occurrence %d is saved at (%v,%v) but its observations replay to (%v,%v)", ErrCorrupt, id, num, x, y, a.x, a.y)
644				}
645				return nil
646			}
647			for _, lm := range fd.Landmarks {
648				if len(lm.Occurrences) == 0 {
649					if err := checkPosition(lm.ID, 1, lm.X, lm.Y); err != nil {
650						return err
651					}
652					continue
653				}
654				for _, oj := range lm.Occurrences {
655					if err := checkPosition(lm.ID, oj.Number, oj.X, oj.Y); err != nil {
656						return err
657					}
658				}
659			}
660	
661			// “截至每一帧”的累计已接纳观测统计，供逐条校正记录按各自结束时间
662			// 核对次数。同帧对同一标识的多条观测各计一次，无观测帧不增加；
663			// null 旧帧没有逐帧观测，running 不增长——其贡献固定在该出现的
664			// LegacyCount 中，使用时经 legacyByKey 另加，不能按零处理也不能
665			// 按帧数推测。无法归组的观测在上面的归属校验中已被拒绝，这里跳过
666			// 即可。只为校正结束帧所在下标复制快照（已在 cumBySrc 预登记），
667			// 各快照相互独立，后续帧的增长不改写旧快照。
668			running := make(map[occurrenceKey]int)
669			for k, src := range fd.Sources {
670				if src != nil {
671					t := fd.Trajectory[k+1].Time
672					for _, ob := range src.Observations {
673						if num, known := replay.occurrenceOf(ob.ID, t); known && num != 0 {
674							running[occurrenceKey{id: ob.ID, num: num}]++
675						}
676					}
677				}
678				if _, need := cumBySrc[k]; need {
679					snap := make(map[occurrenceKey]int, len(running))
680					for key, c := range running {
681						snap[key] = c
682					}
683					cumBySrc[k] = snap
684				}
685			}
686			// 各次出现保存的固定旧观测贡献次数（旧地图缺少逐帧依据的既有观
687			// 测），作为所属出现的既有贡献计入截至记录结束时间的总数。
688			legacyByKey = make(map[occurrenceKey]int, len(fd.Landmarks))
689			for _, lm := range fd.Landmarks {
690				if len(lm.Occurrences) == 0 {
691					legacyByKey[occurrenceKey{id: lm.ID, num: 1}] = lm.LegacyCount
692					continue
693				}
694				for _, oj := range lm.Occurrences {
695					legacyByKey[occurrenceKey{id: lm.ID, num: oj.Number}] = oj.LegacyCount
696				}
697			}
698		}
699		segIDs := make(map[string]struct{}, len(fd.Segments))
700		for _, sg := range fd.Segments {
701			if sg.ID == "" || sg.Hash == "" {
702				return fmt.Errorf("%w: invalid segment record", ErrCorrupt)
703			}
704			if _, dup := segIDs[sg.ID]; dup {
705				return fmt.Errorf("%w: duplicate segment %s", ErrCorrupt, sg.ID)
706			}
707			segIDs[sg.ID] = struct{}{}
708		}
709		corrIDs := make(map[string]struct{}, len(fd.Corrections))
710		for _, cr := range fd.Corrections {
711			if cr.ID == "" || cr.Anchor > cr.EndTime {
712				return fmt.Errorf("%w: invalid correction record", ErrCorrupt)
713			}
714			// 锚点与结束时间必须准确命中已导入帧：trajectory[0] 是初始位姿，
715			// 不是可校正的帧，也不能用相邻帧的时间代替。轨迹时间已在前面
716			// 校验为严格递增，命中即唯一。
717			anchorIdx, endIdx := -1, -1
718			for j := 1; j < len(fd.Trajectory); j++ {
719				if fd.Trajectory[j].Time == cr.Anchor {
720					anchorIdx = j
721				}
722				if fd.Trajectory[j].Time == cr.EndTime {
723					endIdx = j
724				}
725			}
726			if anchorIdx < 0 || endIdx < 0 {
727				return fmt.Errorf("%w: correction %s range does not hit imported frames", ErrCorrupt, cr.ID)
728			}
729			// 记录必须恰好覆盖 [anchor, end] 内的每一帧：位姿条目数量等于
730			// 范围内帧数，按轨迹时间次序一一对应，且同一份前后位姿的时间
731			// 相同并就是对应帧的时间。缺失、重复、错序、额外加入范围外的
732			// 帧，或把前后时间写成两个不同帧，都使记录不能完整描述声明的
733			// 范围，按损坏拒绝。这里只核对覆盖的帧及时间：快照中的位置、
734			// 朝向和方差是提交时的历史值，不要求等于当前轨迹（后来对相同
735			// 范围再校正、或之后导入新帧，都不影响既有记录的合法性）。
736			if len(cr.Poses) != endIdx-anchorIdx+1 {
737				return fmt.Errorf("%w: correction %s does not cover every frame in its range", ErrCorrupt, cr.ID)
738			}
739			for i, pc := range cr.Poses {
740				ft := fd.Trajectory[anchorIdx+i].Time
741				if pc.Before.Time != ft || pc.After.Time != ft {
742					return fmt.Errorf("%w: correction %s pose entry %d does not match frame time %d", ErrCorrupt, cr.ID, i, ft)
743				}
744				if !finitePose(pc.Before) || !finitePose(pc.After) {
745					return fmt.Errorf("%w: correction %s has non-finite pose", ErrCorrupt, cr.ID)
746				}
747			}
748			// 以下两项核对都只针对范围内逐帧依据完整的校正：范围内任一来源
749			// 帧为 null 旧帧时保留旧文件的既有打开规则，不推测运动方差、也
750			// 不把未知贡献当成零；纯旧文件缺省 sources（长度为 0，重放器不构
751			// 建）时所有记录都不核对。同一文件的其余依据完整的记录不受含旧帧
752			// 记录影响，仍逐一核对。
753			fullyBased := len(fd.Sources) != 0
754			if fullyBased {
755				for k := anchorIdx - 1; k <= endIdx-1; k++ {
756					if fd.Sources[k] == nil {
757						fullyBased = false
758						break
759					}
760				}
761			}
762			if fullyBased {
763				// 校正后方差核对：锚点帧的校正后方差必须等于该次提交的目标
764				// 方差；其后每帧在目标方差上，按时间顺序累加锚点之后至该帧
765				// 的原运动方差。锚点自身进入该帧的运动方差不再加一次，也不
766				// 能以校正前方差作为起点；累计范围以本记录自己的锚点与结束
767				// 时间为准，后来对重叠范围的再校正与之后追加的帧都不属于本
768				// 记录。目标方差或参与累计的运动方差为负/非有限、累计结果非
769				// 有限，或与保存的校正后方差不完全一致，都按损坏拒绝整份文
770				// 件——每一帧逐一核对，不能只凭锚点与末帧正确就接受中间错误
771				// 的记录；目标方差与运动方差全为零的合法校正同样逐帧通过。
772				accum := cr.Target.Variance
773				if !isFinite(accum) || accum < 0 {
774					return fmt.Errorf("%w: correction %s target variance is negative or non-finite", ErrCorrupt, cr.ID)
775				}
776				for i, pc := range cr.Poses {
777					if i > 0 {
778						// 记录内第 i 帧位于轨迹下标 anchorIdx+i；进入它的运
779						// 动方差在来源 sources[anchorIdx+i-1]（i=1 即锚点之
780						// 后第一帧），锚点自身的来源 sources[anchorIdx-1] 不
781						// 参与累计。
782						mv := fd.Sources[anchorIdx+i-1].MoveVariance
783						if !isFinite(mv) || mv < 0 {
784							return fmt.Errorf("%w: correction %s accumulates negative or non-finite motion variance at frame time %d", ErrCorrupt, cr.ID, pc.After.Time)
785						}
786						accum += mv
787						if !isFinite(accum) {
788							return fmt.Errorf("%w: correction %s corrected variance accumulates to non-finite value at frame time %d", ErrCorrupt, cr.ID, pc.After.Time)
789						}
790					}
791					if pc.After.Variance != accum {
792						return fmt.Errorf("%w: correction %s pose at frame time %d has corrected variance %v but target variance %v and the motion variances after the anchor accumulate to %v", ErrCorrupt, cr.ID, pc.After.Time, pc.After.Variance, cr.Target.Variance, accum)
793					}
794				}
795				// 几何核对：整条记录必须描述同一次平移和旋转。只核对该记录
796				// 自身保存的校正前后值与目标，不要求历史快照等于当前轨迹——
797				// 后来对重叠范围再校正、或在结束时间之后追加轨迹，都不改写旧
798				// 记录，也不能使原本合法的旧记录被拒绝。重定位规则与 Correct
799				// 提交时共享同一实现（poseShift，见 correction.go）：旋转角、
800				// 余弦正弦与期望位姿的运算次序完全一致，本包写出的合法记录重
801				// 算出的期望值与保存值逐位相同；这里另按容差接纳浮点重算误
802				// 差。锚点的校正后位置必须是目标位置、朝向必须是目标朝向归一
803				// 到 [-π,π) 的结果；其余帧必须与锚点一起做同一次刚体重定
804				// 位：保留校正前相对锚点的位置关系与朝向差。每一帧都逐一核
805				// 对——只有锚点与末帧正确而中间一帧位置偏离或单独转向，同样
806				// 按损坏拒绝；范围只有锚点一帧时本核对即只针对该帧。坐标容差
807				// 为 1e-9 乘以 1、期望值绝对值、保存值绝对值三者的最大值；
808				// 朝向按最短角度差比较，容差 1e-9 弧度。容差与路标合并距离无
809				// 关：合并距离只是导入/校正时的观测接纳门槛，不能用来放过记
810				// 录内部的几何矛盾。目标位置/朝向与锚点校正前完全相同（角度
811				// 等价）时是恒等（只调方差）校正，期望几何直接取校正前值，与
812				// Correct 的同一分支保持一致：横跨 ±1e308 的轨迹上“相对锚
813				// 点偏移”会溢出，不能因此把合法的恒等校正误判为损坏。
814				anchorBefore := cr.Poses[0].Before
815				shift := newPoseShift(cr.Target, anchorBefore)
816				for i, pc := range cr.Poses {
817					var wantX, wantY, wantHeading float64
818					if i == 0 {
819						wantX, wantY, wantHeading = shift.x, shift.y, shift.heading
820					} else {
821						wantX, wantY, wantHeading = shift.apply(pc.Before)
822					}
823					if !coordClose(pc.After.X, wantX) {
824						return fmt.Errorf("%w: correction %s pose at frame time %d has corrected x %v but the record's target and pre-correction poses rigidly move it to %v", ErrCorrupt, cr.ID, pc.After.Time, pc.After.X, wantX)
825					}
826					if !coordClose(pc.After.Y, wantY) {
827						return fmt.Errorf("%w: correction %s pose at frame time %d has corrected y %v but the record's target and pre-correction poses rigidly move it to %v", ErrCorrupt, cr.ID, pc.After.Time, pc.After.Y, wantY)
828					}
829					if !angleClose(pc.After.Heading, wantHeading) {
830						return fmt.Errorf("%w: correction %s pose at frame time %d has corrected heading %v but the record's rotation makes it %v", ErrCorrupt, cr.ID, pc.After.Time, pc.After.Heading, wantHeading)
831					}
832				}
833			}
834			for _, lc := range cr.Landmarks {
835				if lc.ID == "" {
836					return fmt.Errorf("%w: correction %s has empty landmark id", ErrCorrupt, cr.ID)
837				}
838				if lc.Occurrence < 0 || !isFinite(lc.Before.X) || !isFinite(lc.Before.Y) ||
839					!isFinite(lc.After.X) || !isFinite(lc.After.Y) ||
840					lc.Before.Count < 1 || lc.After.Count < 1 {
841					return fmt.Errorf("%w: correction %s has invalid landmark change", ErrCorrupt, cr.ID)
842				}
843			}
844			// 路标列表必须恰好描述记录范围（锚点帧到结束帧，两端包含；之后
845			// 追加的帧不属于范围）内逐帧观测实际涉及的路标出现：范围内被观测
846			// 到的每个（路标，出现编号）必须恰好有一条前后记录，同一次出现被
847			// 多帧或同帧多条观测涉及也只记一条；少记、多记、重复、或把出现
848			// 编号改指该范围没有涉及的另一出现，都按损坏拒绝整份文件，而不是
849			// 只看条目里的坐标与次数是否合法。归组沿用与回环校正相同的时间边
850			// 界规则（重放器，见 replay.go）：同一标识失效后再现属于不同出现，
851			// 即使位置相同也分别对应；已失效的旧出现只要范围内（含失效时刻）
852			// 有它的观测就必须在列表中，不因当前区域查询不再返回它而被排除；
853			// 范围外帧（如记录之后才再现的新出现）的观测不计入。范围内没有
854			// 任何路标观测时列表必须为空，非空即损坏。仅对范围内逐帧依据完整
855			// 的校正做此核对：范围内含 null 旧帧的校正缺少逐帧依据，保留旧地
856			// 图的既有打开规则，不凭推测要求补造观测。
857			if replay != nil && fullyBased {
858				rangeFrames := make([]replayFrame, 0, endIdx-anchorIdx+1)
859				for j := anchorIdx; j <= endIdx; j++ {
860					rangeFrames = append(rangeFrames, replayFrame{time: fd.Trajectory[j].Time, observations: fd.Sources[j-1].Observations})
861				}
862				want := replay.observed(rangeFrames)
863				got := make(map[occurrenceKey]struct{}, len(cr.Landmarks))
864				for _, lc := range cr.Landmarks {
865					num := lc.Occurrence
866					if num == 0 {
867						num = 1 // 更早版本写出的校正记录不带编号，按第 1 次出现解释
868					}
869					if num < 1 || num > replay.occurrences(lc.ID) {
870						return fmt.Errorf("%w: correction %s lists landmark %s occurrence %d not touched by its range", ErrCorrupt, cr.ID, lc.ID, num)
871					}
872					key := occurrenceKey{id: lc.ID, num: num}
873					if _, dup := got[key]; dup {
874						return fmt.Errorf("%w: correction %s lists landmark %s occurrence %d more than once", ErrCorrupt, cr.ID, lc.ID, num)
875					}
876					got[key] = struct{}{}
877				}
878				for key := range want {
879					if _, ok := got[key]; !ok {
880						return fmt.Errorf("%w: correction %s misses landmark %s occurrence %d observed in its range", ErrCorrupt, cr.ID, key.id, key.num)
881					}
882				}
883				for key := range got {
884					if _, ok := want[key]; !ok {
885						return fmt.Errorf("%w: correction %s lists landmark %s occurrence %d with no observation in its range", ErrCorrupt, cr.ID, key.id, key.num)
886					}
887				}
888	
889				// 观测次数核对：回环校正只移动轨迹、不增删已接受观测，因此对
890				// 于依据完整的记录，其每个受影响路标出现的校正前、校正后次数
891				// 都必须等于截至“本记录结束时间”已经接纳、归属该次出现的观
892				// 测总数。这个总数按各记录自己的结束帧从累计快照截取：包含锚
893				// 点之前属于同一次出现的观测与结束帧上的观测，不只是被移动的
894				// [anchor,end] 那段；同帧多条观测各计一次，无观测帧不增加；
895				// 该出现保存的固定旧观测贡献（旧地图既有观测）也要计入，不能
896				// 当作零。结束帧之后才接纳的观测（例如记录结束于 300、后来在
897				// 400 又观测一次）不属于本记录；后来对重叠范围的再次校正不改
898				// 变判断——每条记录都以自己的结束时间为准。各次出现分别核
899				// 对，不能借另一出现的观测补足；已失效的旧出现只要被该条校正
900				// 涉及同样核对。校正前或校正后任一次数不符，即使路标列表、位
901				// 置与文件校验都正常，也按损坏拒绝整份地图。省略出现编号的旧
902				// 条目沿用按第 1 次出现解释的规则。范围内含 null 旧帧时依据不
903				// 完整，保留旧文件的既有打开规则（fullyBased 为假，不到此）。
904				snapshot := cumBySrc[endIdx-1]
905				for _, lc := range cr.Landmarks {
906					num := lc.Occurrence
907					if num == 0 {
908						num = 1
909					}
910					wantCount := snapshot[occurrenceKey{id: lc.ID, num: num}] + legacyByKey[occurrenceKey{id: lc.ID, num: num}]
911					if lc.Before.Count != wantCount {
912						return fmt.Errorf("%w: correction %s landmark %s occurrence %d records %d pre-correction observations but %d were accepted by its end time %d", ErrCorrupt, cr.ID, lc.ID, num, lc.Before.Count, wantCount, cr.EndTime)
913					}
914					if lc.After.Count != wantCount {
915						return fmt.Errorf("%w: correction %s landmark %s occurrence %d records %d post-correction observations but %d were accepted by its end time %d", ErrCorrupt, cr.ID, lc.ID, num, lc.After.Count, wantCount, cr.EndTime)
916					}
917				}
918			}
919			if _, dup := corrIDs[cr.ID]; dup {
920				return fmt.Errorf("%w: duplicate correction %s", ErrCorrupt, cr.ID)
921			}
922			corrIDs[cr.ID] = struct{}{}
923		}
924		// 路标记录按标识索引，供失效记录与出现历史的交叉核对使用。
925		lmByID := make(map[string]*landmarkJSON, len(fd.Landmarks))
926		for i := range fd.Landmarks {
927			lmByID[fd.Landmarks[i].ID] = &fd.Landmarks[i]
928		}
929		invalIDs := make(map[string]struct{}, len(fd.Invalidations))
930		// invalTriples 记录每条失效操作实际引用的（操作标识，路标，出现编号）
931		// 三元组，供反向核对：每个已失效出现都必须是某条操作记录里的实际条目。
932		type invalTriple struct {
933			op  string
934			lm  string
935			num int
936		}
937		invalTriples := make(map[invalTriple]struct{}, len(fd.Invalidations))
938		for _, iv := range fd.Invalidations {
939			if iv.ID == "" || iv.Reason == "" || iv.Hash == "" || len(iv.Landmarks) == 0 {
940				return fmt.Errorf("%w: invalid invalidation record", ErrCorrupt)
941			}
942			if _, dup := invalIDs[iv.ID]; dup {
943				return fmt.Errorf("%w: duplicate invalidation %s", ErrCorrupt, iv.ID)
944			}
945			invalIDs[iv.ID] = struct{}{}
946			lmSeen := make(map[string]struct{}, len(iv.Landmarks))
947			for _, l := range iv.Landmarks {
948				if l.ID == "" || l.Occurrence < 1 {
949					return fmt.Errorf("%w: invalid invalidation landmark entry", ErrCorrupt)
950				}
951				if _, dup := lmSeen[l.ID]; dup {
952					return fmt.Errorf("%w: invalidation %s lists %s twice", ErrCorrupt, iv.ID, l.ID)
953				}
954				lmSeen[l.ID] = struct{}{}
955			}
956			// 交叉核对：成功失效结果里的每个（路标标识，出现编号）必须准确
957			// 指向该路标历史中同编号的那次出现，不能改指同一路标的其他出现，
958			// 也不能因为路标后来再次出现就把旧结果指向最新记录。被指出现必须
959			// 已经失效，且其上记录的失效操作标识、失效时间、失效原因都与这条
960			// 操作记录一致——时间与原因各自再合理也不够，实际由另一条操作撤下
961			// 时不能仅凭相同时间/原因认可。旧版平铺路标视为第 1 次有效出现，
962			// 不可能被失效记录引用（引用即损坏）。一条操作同时撤下多个路标时，
963			// 任意一个条目不满足对应关系都拒绝打开整个文件。
964			for _, l := range iv.Landmarks {
965				lm := lmByID[l.ID]
966				if lm == nil {
967					return fmt.Errorf("%w: invalidation %s result points to unknown landmark %s", ErrCorrupt, iv.ID, l.ID)
968				}
969				if len(lm.Occurrences) == 0 {
970					return fmt.Errorf("%w: invalidation %s result points to flat legacy landmark %s which has no invalidated occurrence", ErrCorrupt, iv.ID, l.ID)
971				}
972				if l.Occurrence > len(lm.Occurrences) {
973					return fmt.Errorf("%w: invalidation %s result points to landmark %s occurrence %d which does not exist", ErrCorrupt, iv.ID, l.ID, l.Occurrence)
974				}
975				// 出现编号连续性已在上方路标校验中强制，该下标处编号即 l.Occurrence。
976				oj := lm.Occurrences[l.Occurrence-1]
977				if oj.Active {
978					return fmt.Errorf("%w: invalidation %s result points to landmark %s occurrence %d which is still active", ErrCorrupt, iv.ID, l.ID, l.Occurrence)
979				}
980				if oj.InvalidOpID != iv.ID || oj.InvalidTime != iv.Time || oj.InvalidReason != iv.Reason {
981					return fmt.Errorf("%w: invalidation %s result for landmark %s occurrence %d does not match its saved invalidation (op %q, time %d, reason %q)", ErrCorrupt, iv.ID, l.ID, l.Occurrence, oj.InvalidOpID, oj.InvalidTime, oj.InvalidReason)
982				}
983				invalTriples[invalTriple{op: iv.ID, lm: l.ID, num: l.Occurrence}] = struct{}{}
984			}
985		}
986		// 反向核对：每个已失效出现都必须能在失效操作序列中找到引用同一（操作，
987		// 路标，出现编号）三元组的条目。正向核对已保证被引用出现的失效时间与
988		// 原因和引用方一致；此处堵住另一方向的矛盾：出现凭空携带失效信息、
989		// 声称撤下它的操作记录实际指向另一次出现，或两次出现声称被同一操作
990		// 撤下（一次操作对同一路标只会撤下当时唯一的有效出现）。旧地图没有
991		// 失效操作时，平铺路标视为有效、不携带失效信息，不会触发；旧地图后来
992		// 产生的失效操作同样在上述核对之列，不要求补齐原本缺失的逐帧观测。
993		for _, lm := range fd.Landmarks {
994			for _, oj := range lm.Occurrences {
995				if oj.Active {
996					continue
997				}
998				if _, ok := invalTriples[invalTriple{op: oj.InvalidOpID, lm: lm.ID, num: oj.Number}]; !ok {
999					return fmt.Errorf("%w: landmark %s occurrence %d is marked invalidated by operation %q which does not record that invalidation", ErrCorrupt, lm.ID, oj.Number, oj.InvalidOpID)
1000				}
1001			}
1002		}
1003		return nil
1004	}
1005	
1006	func finitePose(p Pose) bool {
1007		return isFinite(p.X) && isFinite(p.Y) && isFinite(p.Heading) && isFinite(p.Variance)
1008	}
1009	
1010	// geomTol 是打开时核对校正记录几何一致性的相对容差（另含 1 的绝对项）。
1011	const geomTol = 1e-9
1012	
1013	// coordClose 判断保存坐标 got 是否在容许误差内等于期望 want：误差不得
1014	// 超过 geomTol 乘以 1、|want|、|got| 三者中的最大值。参与比较的值都已
1015	// 校验为有限，差值必有限，NaN 不会混入并被误当相等。
1016	func coordClose(got, want float64) bool {
1017		scale := math.Max(1, math.Max(math.Abs(want), math.Abs(got)))
1018		return math.Abs(got-want) <= geomTol*scale
1019	}
1020	
1021	// angleClose 按最短角度差判断两个角度是否相等，容差 geomTol 弧度。两个
1022	// 角度都已校验为有限；差值经归一化到 [-π,π) 即最短角度差，正确处理
1023	// ±π 附近跨边界但物理方向相同的情形。
1024	func angleClose(got, want float64) bool {
1025		return math.Abs(normalizeAngle(got-want)) <= geomTol
1026	}
1027	
1028	// canonicalCorrectionHash 计算一次校正请求（锚点时间 + 目标位姿）的
1029	// 确定性指纹，用于同标识重复提交判定。直接按 IEEE-754 位编码。
1030	func canonicalCorrectionHash(anchor int64, tgt CorrectionTarget) string {
1031		h := sha256.New()
1032		var b [8]byte
1033		binary.BigEndian.PutUint64(b[:], uint64(anchor))
1034		h.Write(b[:])
1035		for _, v := range []float64{tgt.X, tgt.Y, tgt.Heading, tgt.Variance} {
1036			binary.BigEndian.PutUint64(b[:], math.Float64bits(v))
1037			h.Write(b[:])
1038		}
1039		return fmt.Sprintf("%x", h.Sum(nil))
1040	}
1041	
1042	// saveExclusive 创建新文件，目标已存在即失败（O_EXCL）。
1043	func (m *Map) saveExclusive() error {
1044		data, err := encodeFile(m.state)
1045		if err != nil {
1046			return err
1047		}
1048		f, err := os.OpenFile(m.path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
1049		if err != nil {
1050			return err
1051		}
1052		return writeAndClose(f, data, m.path)
1053	}
1054	
1055	// saveReplace 用同目录临时文件 + rename 原子替换现有文件。
1056	func (m *Map) saveReplace() (err error) {
1057		data, err := encodeFile(m.state)
1058		if err != nil {
1059			return err
1060		}
1061		dir, base := filepath.Split(m.path)
1062		if dir == "" {
1063			dir = "."
1064		}
1065		f, err := os.CreateTemp(dir, base+".tmp-*")
1066		if err != nil {
1067			return err
1068		}
1069		tmpName := f.Name()
1070		// 任何失败路径都尽力清理临时文件。
1071		defer func() {
1072			if err != nil {
1073				_ = os.Remove(tmpName)
1074			}
1075		}()
1076		if err = writeAndClose(f, data, tmpName); err != nil {
1077			return err
1078		}
1079		if err = os.Rename(tmpName, m.path); err != nil {
1080			return err
1081		}
1082		return nil
1083	}
1084	
1085	func writeAndClose(f *os.File, data []byte, name string) (err error) {
1086		defer func() {
1087			if cerr := f.Close(); err == nil {
1088				err = cerr
1089			}
1090		}()
1091		if _, err = f.Write(data); err != nil {
1092			return err
1093		}
1094		if err = f.Sync(); err != nil {
1095			return err
1096		}
1097		return nil
1098	}
1099	
1100	// canonicalHash 计算一批帧的确定性指纹，用于重复导入判定。直接按
1101	// IEEE-754 位编码，NaN/Inf 也有稳定表示，不依赖 JSON 对其不支持的问题。
1102	func canonicalHash(frames []Frame) string {
1103		h := sha256.New()
1104		var lenBuf [4]byte
1105		var numBuf [8]byte
1106		putU32 := func(v uint32) {
1107			binary.BigEndian.PutUint32(lenBuf[:], v)
1108			h.Write(lenBuf[:])
1109		}
1110		putU64 := func(v uint64) {
1111			binary.BigEndian.PutUint64(numBuf[:], v)
1112			h.Write(numBuf[:])
1113		}
1114		putStr := func(s string) {
1115			putU32(uint32(len(s)))
1116			h.Write([]byte(s))
1117		}
1118	
1119		putU32(uint32(len(frames)))
1120		for _, fr := range frames {
1121			putU64(uint64(fr.Time))
1122			putU64(math.Float64bits(fr.DX))
1123			putU64(math.Float64bits(fr.DY))
1124			putU64(math.Float64bits(fr.DHeading))
1125			putU64(math.Float64bits(fr.MoveVariance))
1126			putU32(uint32(len(fr.Observations)))
1127			for _, ob := range fr.Observations {
1128				putStr(ob.ID)
1129				putU64(math.Float64bits(ob.X))
1130				putU64(math.Float64bits(ob.Y))
1131			}
1132		}
1133		return fmt.Sprintf("%x", h.Sum(nil))
1134	}
1135

file.content:
package posemap

import (
	"crypto/sha256"
	"encoding/binary"
	"encoding/json"
	"fmt"
	"hash/crc32"
	"math"
	"os"
	"path/filepath"
)

// 文件布局（均为大端）：
//
//	magic     8 字节  "POSEMAP1"
//	version   uint16
//	length    uint32  payload 字节数
//	payload   length 字节（JSON，见 fileData）
//	crc       uint32  对 crc 之前全部字节的 CRC-32/IEEE
//
// 保存采用“同目录临时文件写完并 fsync 后 rename”的方式，成功导入对
// 调用方可见时文件必为完整的新版本；无法识别或校验失败的文件绝不被
// 覆盖（Create 用 O_EXCL，Open 只读取证）。
// 文件格式在版本 1 内以“追加 JSON 字段”的方式演进：旧文件不含
// sources/corrections 字段（解码后为 nil/空），据此识别缺少逐帧依据的
// 旧地图；二进制版本号保持 1，不支持的版本号仍按既有约定拒绝。
const (
	fileMagic   = "POSEMAP1"
	fileVersion = uint16(1)
	headerLen   = 8 + 2 + 4
)

type fileData struct {
	Version       int             `json:"version"`
	Config        Config          `json:"config"`
	Trajectory    []Pose          `json:"trajectory"`
	Landmarks     []landmarkJSON  `json:"landmarks"`
	Segments      []segmentJSON   `json:"segments"`
	Sources       []*frameSrcJSON `json:"sources,omitempty"`       // 新格式：逐帧依据，旧帧为 null；旧文件整列缺省
	Corrections   []corrRecJSON   `json:"corrections,omitempty"`   // 新格式：按提交次序的校正记录
	Invalidations []invalJSON     `json:"invalidations,omitempty"` // 新格式：按提交次序的失效操作
}

type landmarkJSON struct {
	ID          string           `json:"id"`
	Occurrences []occurrenceJSON `json:"occurrences,omitempty"` // 新格式：历次出现，编号递增
	// 以下平铺字段仅用于读取不携带 occurrences 的旧文件。
	X           float64 `json:"x,omitempty"`
	Y           float64 `json:"y,omitempty"`
	Count       int     `json:"count,omitempty"`
	LegacyCount int     `json:"legacy_count,omitempty"`
	LegacyMX    float64 `json:"legacy_mx,omitempty"`
	LegacyMY    float64 `json:"legacy_my,omitempty"`
}

type occurrenceJSON struct {
	Number        int     `json:"number"` // 出现编号，从 1 开始连续
	X             float64 `json:"x"`
	Y             float64 `json:"y"`
	Count         int     `json:"count"`
	LegacyCount   int     `json:"legacy_count,omitempty"`
	LegacyMX      float64 `json:"legacy_mx,omitempty"`
	LegacyMY      float64 `json:"legacy_my,omitempty"`
	FirstSeenTime int64   `json:"first_seen_time,omitempty"`
	HasFirstSeen  bool    `json:"has_first_seen"`
	Active        bool    `json:"active"`
	InvalidTime   int64   `json:"invalid_time,omitempty"`
	InvalidReason string  `json:"invalid_reason,omitempty"`
	InvalidOpID   string  `json:"invalid_op_id,omitempty"`
}

type invalJSON struct {
	ID        string        `json:"id"`
	Reason    string        `json:"reason"`
	Hash      string        `json:"hash"`
	Time      int64         `json:"time"`
	Landmarks []invalLMJSON `json:"landmarks"`
}

type invalLMJSON struct {
	ID         string `json:"id"`
	Occurrence int    `json:"occurrence"`
}

type segmentJSON struct {
	ID     string       `json:"id"`
	Hash   string       `json:"hash"`
	Result ImportResult `json:"result"`
}

type frameSrcJSON struct {
	MoveVariance float64       `json:"move_variance"`
	Observations []Observation `json:"observations"`
}

type poseChangeJSON struct {
	Before Pose `json:"before"`
	After  Pose `json:"after"`
}

type landmarkChangeJSON struct {
	ID         string   `json:"id"`
	Occurrence int      `json:"occurrence"` // 受影响的出现编号（1 起）；旧校正记录缺省为 1
	Before     Landmark `json:"before"`
	After      Landmark `json:"after"`
}

type corrRecJSON struct {
	ID        string               `json:"id"`
	Anchor    int64                `json:"anchor"`
	Target    CorrectionTarget     `json:"target"`
	EndTime   int64                `json:"end_time"`
	Poses     []poseChangeJSON     `json:"poses"`
	Landmarks []landmarkChangeJSON `json:"landmarks"`
}

// encodeFile 把内存状态编码为完整文件字节。
func encodeFile(st *mapState) ([]byte, error) {
	fd := fileData{
		Version:       int(fileVersion),
		Config:        st.config,
		Trajectory:    st.trajectory,
		Landmarks:     make([]landmarkJSON, 0, len(st.landmarks)),
		Segments:      make([]segmentJSON, 0, len(st.segments)),
		Sources:       make([]*frameSrcJSON, len(st.sources)),
		Corrections:   make([]corrRecJSON, 0, len(st.corrections)),
		Invalidations: make([]invalJSON, 0, len(st.invalRecords)),
	}
	for id, lm := range st.landmarks {
		lj := landmarkJSON{ID: id, Occurrences: make([]occurrenceJSON, 0, len(lm.appearances))}
		for i, occ := range lm.appearances {
			oj := occurrenceJSON{
				Number:        i + 1,
				X:             occ.x,
				Y:             occ.y,
				Count:         occ.count,
				LegacyCount:   occ.legacyCount,
				LegacyMX:      occ.legacyMX,
				LegacyMY:      occ.legacyMY,
				FirstSeenTime: occ.firstSeenTime,
				HasFirstSeen:  occ.hasFirstSeen,
				Active:        occ.active,
			}
			if !occ.active {
				oj.InvalidTime = occ.invalidTime
				oj.InvalidReason = occ.invalidReason
				oj.InvalidOpID = occ.invalidOpID
			}
			lj.Occurrences = append(lj.Occurrences, oj)
		}
		fd.Landmarks = append(fd.Landmarks, lj)
	}
	for id, rec := range st.segments {
		fd.Segments = append(fd.Segments, segmentJSON{ID: id, Hash: rec.hash, Result: rec.result})
	}
	for k, src := range st.sources {
		if src == nil {
			continue // 旧文件帧在新文件中保留为 null，表示仍无逐帧依据
		}
		obs := append([]Observation(nil), src.observations...)
		fd.Sources[k] = &frameSrcJSON{MoveVariance: src.moveVariance, Observations: obs}
	}
	for _, rec := range st.corrections {
		cj := corrRecJSON{
			ID:        rec.ID,
			Anchor:    rec.Anchor,
			Target:    rec.Target,
			EndTime:   rec.EndTime,
			Poses:     make([]poseChangeJSON, len(rec.Poses)),
			Landmarks: make([]landmarkChangeJSON, len(rec.Landmarks)),
		}
		for i, pc := range rec.Poses {
			cj.Poses[i] = poseChangeJSON{Before: pc.Before, After: pc.After}
		}
		for i, lc := range rec.Landmarks {
			cj.Landmarks[i] = landmarkChangeJSON{ID: lc.ID, Occurrence: lc.Occurrence, Before: lc.Before, After: lc.After}
		}
		fd.Corrections = append(fd.Corrections, cj)
	}
	for _, rec := range st.invalRecords {
		ij := invalJSON{
			ID:        rec.id,
			Reason:    rec.reason,
			Hash:      rec.hash,
			Time:      rec.result.Time,
			Landmarks: make([]invalLMJSON, len(rec.result.Landmarks)),
		}
		for i, l := range rec.result.Landmarks {
			ij.Landmarks[i] = invalLMJSON{ID: l.ID, Occurrence: l.Occurrence}
		}
		fd.Invalidations = append(fd.Invalidations, ij)
	}
	payload, err := json.Marshal(&fd)
	if err != nil {
		return nil, fmt.Errorf("posemap: encode state: %w", err)
	}

	out := make([]byte, headerLen+len(payload)+4)
	copy(out[0:8], fileMagic)
	binary.BigEndian.PutUint16(out[8:10], fileVersion)
	binary.BigEndian.PutUint32(out[10:14], uint32(len(payload)))
	copy(out[headerLen:], payload)
	sum := crc32.ChecksumIEEE(out[:headerLen+len(payload)])
	binary.BigEndian.PutUint32(out[headerLen+len(payload):], sum)
	return out, nil
}

// loadFile 只读取证地解析地图文件。
func loadFile(path string) (*mapState, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, err // 含 fs.ErrNotExist，交由调用方/上层用 errors.Is 判断
	}
	if len(raw) < headerLen+4 || string(raw[:8]) != fileMagic {
		return nil, fmt.Errorf("%w: unrecognized header", ErrCorrupt)
	}
	version := binary.BigEndian.Uint16(raw[8:10])
	if version != fileVersion {
		return nil, fmt.Errorf("%w: version %d", ErrUnsupportedVersion, version)
	}
	length := binary.BigEndian.Uint32(raw[10:14])
	if int(length) != len(raw)-headerLen-4 {
		return nil, fmt.Errorf("%w: truncated or length mismatch", ErrCorrupt)
	}
	want := binary.BigEndian.Uint32(raw[len(raw)-4:])
	if crc32.ChecksumIEEE(raw[:len(raw)-4]) != want {
		return nil, fmt.Errorf("%w: checksum mismatch", ErrCorrupt)
	}

	var fd fileData
	if err := json.Unmarshal(raw[headerLen:headerLen+int(length)], &fd); err != nil {
		return nil, fmt.Errorf("%w: %v", ErrCorrupt, err)
	}
	if err := validateLoaded(&fd); err != nil {
		return nil, err
	}

	st := &mapState{
		config:       fd.Config,
		trajectory:   fd.Trajectory,
		landmarks:    make(map[string]*landmarkState, len(fd.Landmarks)),
		segments:     make(map[string]*segmentRecord, len(fd.Segments)),
		sources:      make([]*frameSource, len(fd.Trajectory)-1),
		corrections:  make([]*CorrectionRecord, 0, len(fd.Corrections)),
		corrIndex:    make(map[string]string, len(fd.Corrections)),
		invalRecords: make([]*invalidationRecord, 0, len(fd.Invalidations)),
		invalIndex:   make(map[string]*invalidationRecord, len(fd.Invalidations)),
	}
	// 旧文件不携带逐帧依据：有帧而 sources 缺省即旧地图。无帧时二者
	// 无法区分也无需区分（尚无范围可校正）。
	oldFormat := len(fd.Sources) == 0 && len(fd.Trajectory) > 1
	for _, lmj := range fd.Landmarks {
		lm := &landmarkState{}
		if len(lmj.Occurrences) > 0 {
			// 新格式：历次出现按编号递增保存。
			for _, oj := range lmj.Occurrences {
				lm.appearances = append(lm.appearances, &occurrenceState{
					x:             oj.X,
					y:             oj.Y,
					count:         oj.Count,
					legacyCount:   oj.LegacyCount,
					legacyMX:      oj.LegacyMX,
					legacyMY:      oj.LegacyMY,
					firstSeenTime: oj.FirstSeenTime,
					hasFirstSeen:  oj.HasFirstSeen,
					active:        oj.Active,
					invalidTime:   oj.InvalidTime,
					invalidReason: oj.InvalidReason,
					invalidOpID:   oj.InvalidOpID,
				})
			}
		} else {
			// 兼容旧布局：一个平铺路标即第 1 次有效出现。
			occ := &occurrenceState{
				x:      lmj.X,
				y:      lmj.Y,
				count:  lmj.Count,
				active: true,
			}
			if oldFormat {
				// 旧文件中该路标的全部既有观测都是固定旧贡献，位置取
				// 文件中的聚合值；缺少逐帧来源，首次观测时间未知。
				occ.legacyCount = lmj.Count
				occ.legacyMX, occ.legacyMY = lmj.X, lmj.Y
				occ.hasFirstSeen = false
			} else {
				occ.legacyCount = lmj.LegacyCount
				occ.legacyMX, occ.legacyMY = lmj.LegacyMX, lmj.LegacyMY
				// 含固定旧贡献时最早观测缺少来源，首次观测时间未知；
				// 否则从逐帧依据中恢复该出现第一次被观测到的帧时间。
				occ.hasFirstSeen = lmj.LegacyCount == 0
				if occ.hasFirstSeen {
					for k, src := range fd.Sources {
						if src == nil {
							continue
						}
						found := false
						for _, ob := range src.Observations {
							if ob.ID == lmj.ID {
								found = true
								break
							}
						}
						if found {
							occ.firstSeenTime = fd.Trajectory[k+1].Time
							break
						}
					}
				}
			}
			lm.appearances = append(lm.appearances, occ)
		}
		st.landmarks[lmj.ID] = lm
	}
	for _, sg := range fd.Segments {
		ids := sg.Result.LandmarkIDs
		if ids == nil {
			ids = []string{}
		}
		st.segments[sg.ID] = &segmentRecord{
			hash:   sg.Hash,
			result: ImportResult{EndPose: sg.Result.EndPose, LandmarkIDs: ids},
		}
	}
	if !oldFormat {
		for k, src := range fd.Sources {
			if src == nil {
				continue // 来自旧文件的帧：保持依据缺失
			}
			obs := append([]Observation(nil), src.Observations...)
			st.sources[k] = &frameSource{moveVariance: src.MoveVariance, observations: obs}
		}
	}
	for _, cj := range fd.Corrections {
		rec := &CorrectionRecord{
			ID:        cj.ID,
			Anchor:    cj.Anchor,
			Target:    cj.Target,
			EndTime:   cj.EndTime,
			Poses:     make([]PoseChange, len(cj.Poses)),
			Landmarks: make([]LandmarkChange, len(cj.Landmarks)),
		}
		for i, pc := range cj.Poses {
			rec.Poses[i] = PoseChange{Before: pc.Before, After: pc.After}
		}
		for i, lc := range cj.Landmarks {
			occNum := lc.Occurrence
			if occNum == 0 {
				occNum = 1 // 更早版本写出的校正记录不带编号，只有第 1 次出现
			}
			rec.Landmarks[i] = LandmarkChange{ID: lc.ID, Occurrence: occNum, Before: lc.Before, After: lc.After}
		}
		st.corrections = append(st.corrections, rec)
		st.corrIndex[cj.ID] = canonicalCorrectionHash(cj.Anchor, cj.Target)
	}
	for _, ij := range fd.Invalidations {
		lms := make([]InvalidatedLandmark, len(ij.Landmarks))
		for i, l := range ij.Landmarks {
			lms[i] = InvalidatedLandmark{ID: l.ID, Occurrence: l.Occurrence}
		}
		rec := &invalidationRecord{
			id:     ij.ID,
			reason: ij.Reason,
			hash:   ij.Hash,
			result: InvalidationResult{Time: ij.Time, Landmarks: lms},
		}
		st.invalRecords = append(st.invalRecords, rec)
		st.invalIndex[ij.ID] = rec
	}
	return st, nil
}

// validateLoaded 对解码后的状态做基本不变量检查，违背即视为损坏。
func validateLoaded(fd *fileData) error {
	switch {
	case fd.Version != int(fileVersion):
		return fmt.Errorf("%w: version %d in payload", ErrUnsupportedVersion, fd.Version)
	case len(fd.Trajectory) == 0:
		return fmt.Errorf("%w: empty trajectory", ErrCorrupt)
	}
	if err := validateConfig(fd.Config); err != nil {
		// 配置不合法不可能由本版本写出。
		return fmt.Errorf("%w: %v", ErrCorrupt, err)
	}
	// 保存的整条轨迹必须满足与导入时相同的时间规则：从初始位姿起
	// 时间严格递增，且相邻位姿的真实间隔不超过 MaxInterval（恰好
	// 等于上限合法）。任何一处相等、倒退或超限都使按时间查询失去
	// 可靠的先后依据，整份文件按损坏拒绝。间隔按真实差值判断：前
	// 一时间接近 math.MinInt64 而后一时间为非负时，有符号减法会
	// 溢出回绕成负数，把超限的巨大缺口放过去；此处已保证递增，真
	// 实差值落在 [1, 2^64-1]，用无符号减法取精确的数学差值再与上
	// 限比较（MaxInterval 已校验为正）。
	for i := 1; i < len(fd.Trajectory); i++ {
		prev, cur := fd.Trajectory[i-1].Time, fd.Trajectory[i].Time
		if cur <= prev {
			return fmt.Errorf("%w: trajectory time at pose %d is not strictly increasing", ErrCorrupt, i)
		}
		if uint64(cur)-uint64(prev) > uint64(fd.Config.MaxInterval) {
			return fmt.Errorf("%w: trajectory interval between poses %d and %d exceeds max interval", ErrCorrupt, i-1, i)
		}
	}
	// 新格式的逐帧依据必须与轨迹（除初始位姿外）一一对应；旧文件缺省
	// 该字段（解码为 nil），数量为 0。
	if len(fd.Sources) != 0 && len(fd.Sources) != len(fd.Trajectory)-1 {
		return fmt.Errorf("%w: frame sources length %d for %d frames", ErrCorrupt, len(fd.Sources), len(fd.Trajectory)-1)
	}
	seenIDs := make(map[string]struct{}, len(fd.Landmarks))
	for _, lm := range fd.Landmarks {
		if lm.ID == "" {
			return fmt.Errorf("%w: invalid landmark record", ErrCorrupt)
		}
		if _, dup := seenIDs[lm.ID]; dup {
			return fmt.Errorf("%w: duplicate landmark %s", ErrCorrupt, lm.ID)
		}
		seenIDs[lm.ID] = struct{}{}
		if len(lm.Occurrences) == 0 {
			// 兼容旧布局：平铺字段表示第 1 次出现。
			if lm.Count < 1 || !isFinite(lm.X) || !isFinite(lm.Y) {
				return fmt.Errorf("%w: invalid landmark record", ErrCorrupt)
			}
			if lm.LegacyCount < 0 || lm.LegacyCount > lm.Count {
				return fmt.Errorf("%w: invalid legacy count for landmark %s", ErrCorrupt, lm.ID)
			}
			if lm.LegacyCount > 0 && (!isFinite(lm.LegacyMX) || !isFinite(lm.LegacyMY)) {
				return fmt.Errorf("%w: invalid legacy mean for landmark %s", ErrCorrupt, lm.ID)
			}
			continue
		}
		activeCount := 0
		for i, oj := range lm.Occurrences {
			if oj.Number != i+1 || oj.Count < 1 || !isFinite(oj.X) || !isFinite(oj.Y) {
				return fmt.Errorf("%w: invalid occurrence for landmark %s", ErrCorrupt, lm.ID)
			}
			if oj.LegacyCount < 0 || oj.LegacyCount > oj.Count {
				return fmt.Errorf("%w: invalid legacy count for landmark %s occurrence %d", ErrCorrupt, lm.ID, oj.Number)
			}
			if oj.LegacyCount > 0 && (!isFinite(oj.LegacyMX) || !isFinite(oj.LegacyMY)) {
				return fmt.Errorf("%w: invalid legacy mean for landmark %s occurrence %d", ErrCorrupt, lm.ID, oj.Number)
			}
			if oj.Active {
				activeCount++
				if i != len(lm.Occurrences)-1 {
					return fmt.Errorf("%w: active occurrence %d of landmark %s is not the latest", ErrCorrupt, oj.Number, lm.ID)
				}
			} else if oj.InvalidReason == "" {
				return fmt.Errorf("%w: invalidated occurrence %d of landmark %s lacks reason", ErrCorrupt, oj.Number, lm.ID)
			}
			// 出现编号即先后次序，各次出现接纳观测的时间范围必须与之
			// 相容，否则同一观测可能同时属于两次出现（归属校验只确认能
			// 归入某一次，不排除同时归入两次）。已失效且首次观测时间
			// 已知的出现，首次观测不能晚于失效；下一次出现的首次观测
			// 必须严格晚于上一次的失效时间——首次观测与失效两个端点都
			// 接纳所在时刻的观测，相等即重叠。第 2 次及以后的出现必定
			// 在上一次失效之后由本包创建，首次观测时间必须已知；只有
			// 旧文件的第 1 次出现允许未知（无下界，不把零当作起点）。
			// 这些检查针对保存的出现记录本身，与重叠范围内当前是否有
			// 观测无关。
			if !oj.Active && oj.HasFirstSeen && oj.FirstSeenTime > oj.InvalidTime {
				return fmt.Errorf("%w: occurrence %d of landmark %s first seen at %d after invalidation at %d", ErrCorrupt, oj.Number, lm.ID, oj.FirstSeenTime, oj.InvalidTime)
			}
			if i > 0 {
				if !oj.HasFirstSeen {
					return fmt.Errorf("%w: occurrence %d of landmark %s lacks first seen time", ErrCorrupt, oj.Number, lm.ID)
				}
				// 上一次出现必已失效（仍有效且非最后一次已在上面拒绝）。
				if prev := lm.Occurrences[i-1]; oj.FirstSeenTime <= prev.InvalidTime {
					return fmt.Errorf("%w: occurrence %d of landmark %s starts at %d before previous invalidation at %d", ErrCorrupt, oj.Number, lm.ID, oj.FirstSeenTime, prev.InvalidTime)
				}
			}
		}
		if activeCount > 1 {
			return fmt.Errorf("%w: multiple active occurrences for landmark %s", ErrCorrupt, lm.ID)
		}
	}
	// 观测重放器：各路标历次出现的时间边界（归属规则见 occurrence.go）
	// 与逐条重建位置的流程（见 replay.go）和回环校正共享同一实现；来源
	// 帧的归属核对、次数/首次时间统计、位置核对与校正记录路标列表核对
	// 都经由它进行。旧文件缺省 sources（解码为 nil）时不构建，这些核对
	// 都不进行。
	var replay *observationReplay
	// cumBySrc 仅在逐帧依据存在时构建：键为来源下标 k（对应帧
	// trajectory[k+1]），值为从首帧到该帧（两端含）为止按时间边界归属
	// 各次出现的累计已接纳观测条数快照，只为某条校正记录结束帧所在的下
	// 标保存。次数核对按各记录自己的结束帧取对应快照，再加该出现保存的
	// 固定旧贡献（legacyByKey）。
	var cumBySrc map[int]map[occurrenceKey]int
	var legacyByKey map[occurrenceKey]int
	if len(fd.Sources) != 0 {
		replay = newObservationReplay(fd.Config.MergeDistance)
		for _, lm := range fd.Landmarks {
			replay.track(lm.ID, occurrenceWindowsOf(lm))
		}
		// 预登记各校正记录结束帧对应的来源下标，只为这些下标保留累计快
		// 照，避免对每一帧都复制整份计数。
		cumBySrc = make(map[int]map[occurrenceKey]int, len(fd.Corrections))
		for _, cr := range fd.Corrections {
			for j := 1; j < len(fd.Trajectory); j++ {
				if fd.Trajectory[j].Time == cr.EndTime {
					cumBySrc[j-1] = nil
					break
				}
			}
		}
	}
	// 校验每条带逐帧依据的观测来源：观测路标必须存在，且所在帧时间必须
	// 落入该路标某一次出现的时间边界（共享规则见 occurrence.go）。旧出现
	// 已失效不代表其历史观测无效；同一标识两次出现之间（如 200 失效、
	// 300 再现时的 250 帧）的观测没有归属，按损坏拒绝。null 帧来自缺少
	// 逐帧依据的旧地图，其观测不在这里（也无法）核验；旧版平铺路标视为
	// 一次无边界的有效出现，因此旧地图后来追加的来源帧仍按此规则检查。
	if len(fd.Sources) != 0 {
		// 归属校验的同时按（路标，出现编号）统计来源观测条数：每条观测
		// 各算一次，同帧重复观测同一标识不去重，空观测帧不计。null 帧
		// 缺少逐帧依据，其贡献已固定在出现的旧观测计数中，不在此统计，
		// 也不能按帧数猜测。同时记录归属各次出现的最早来源观测帧时间，
		// 供下方首次观测时间核对使用。
		tallies := make(map[string]map[int]int, len(fd.Landmarks))
		firstObs := make(map[string]map[int]int64, len(fd.Landmarks))
		for k, src := range fd.Sources {
			if src == nil {
				continue // 旧地图帧：无逐帧依据，不要求补齐归属
			}
			t := fd.Trajectory[k+1].Time
			for _, ob := range src.Observations {
				num, known := replay.occurrenceOf(ob.ID, t)
				if !known {
					return fmt.Errorf("%w: observation of unknown landmark %s at frame time %d", ErrCorrupt, ob.ID, t)
				}
				if num == 0 {
					return fmt.Errorf("%w: observation of landmark %s at frame time %d belongs to no occurrence", ErrCorrupt, ob.ID, t)
				}
				c := tallies[ob.ID]
				if c == nil {
					c = make(map[int]int, 1)
					tallies[ob.ID] = c
				}
				c[num]++
				f := firstObs[ob.ID]
				if f == nil {
					f = make(map[int]int64, 1)
					firstObs[ob.ID] = f
				}
				if cur, ok := f[num]; !ok || t < cur {
					f[num] = t
				}
			}
		}
		// 每次出现记录的观测次数必须等于归属该次出现的来源观测条数加上
		// 该次出现已保存的旧观测贡献：偏多或偏少都是文件损坏。各次出现
		// 分别核对，不能用另一次出现的观测补足；已失效的旧出现同样核对，
		// 不因它不再参与区域查询而跳过。回环校正只改位置不改已接受观测
		// 次数，正常校正后保存的文件仍满足此不变量。
		for _, lm := range fd.Landmarks {
			if len(lm.Occurrences) == 0 {
				// 旧版平铺路标即第 1 次出现。
				if got := tallies[lm.ID][1] + lm.LegacyCount; got != lm.Count {
					return fmt.Errorf("%w: landmark %s records %d observations but sources and legacy contributions account for %d", ErrCorrupt, lm.ID, lm.Count, got)
				}
				continue
			}
			for _, oj := range lm.Occurrences {
				if got := tallies[lm.ID][oj.Number] + oj.LegacyCount; got != oj.Count {
					return fmt.Errorf("%w: landmark %s occurrence %d records %d observations but sources and legacy contributions account for %d", ErrCorrupt, lm.ID, oj.Number, oj.Count, got)
				}
			}
		}

		// 首次观测时间核对：首次观测时间已知、且全部观测都具有逐帧来源
		// （无固定旧贡献）的每次出现，记录的首次时间必须准确等于实际归属
		// 该次出现的最早来源观测帧时间。写早或写晚都是损坏：错误时间即使
		// 恰好命中某个已保存的帧，只要该帧没有观测这一路标也不能接受；
		// 错误时间没有对应帧同样拒绝。各次出现分别核对——已失效的旧出现
		// 与失效后再现的新出现各自依据自己的观测判断，不能互相代替；后续
		// 帧继续观测或同帧重复观测都不改变首次时间。时间为零或负数是合法
		// 帧时间，按实际值比较，不把零当作时间未知。旧文件第 1 次出现缺
		// 少旧观测依据、首次时间未知（HasFirstSeen 为假），或仍含固定旧
		// 贡献时，其最早观测无从核对，保留旧地图的既有打开规则；但旧路标
		// 失效后新导入产生的出现依据完整、首次时间已知，不因同一文件存在
		// 旧历史而跳过核对。回环校正只改位姿与位置，不改观测帧时间，已正
		// 确保存的校正地图仍满足此不变量。
		for _, lm := range fd.Landmarks {
			for _, oj := range lm.Occurrences {
				if !oj.HasFirstSeen || oj.LegacyCount > 0 {
					continue
				}
				// 次数核对已保证 Count-LegacyCount 条来源观测存在，最早
				// 帧时间必然已记录；缺失本身即矛盾。
				first, ok := firstObs[lm.ID][oj.Number]
				if !ok || first != oj.FirstSeenTime {
					return fmt.Errorf("%w: landmark %s occurrence %d records first seen time %d but its earliest sourced observation is at frame time %d", ErrCorrupt, lm.ID, oj.Number, oj.FirstSeenTime, first)
				}
			}
		}

		// 位置核对：次数相符只说明观测“条数”对得上，还必须核对保存的路标
		// 位置确实是这些观测依据当前保存位姿重放后的等权平均。每条来源观测
		// 按所在帧当前保存的位姿转换到地图坐标，按帧时间升序、同帧按输入
		// 次序，归入各自出现分别重放；同帧对同一标识的多条观测各自参与，
		// 空观测帧不增加贡献。归组、固定旧贡献起点与逐条重建全部经由与
		// 回环校正共享的重放器（见 replay.go，单条接纳规则见 aggregate.go），
		// 旧文件固定旧贡献（LegacyCount 次平均）作为聚合起点——不能当成零，
		// 也不能用缺少依据的帧数代替。回环校正后保存的文件按当前轨迹重放
		// 即得到当前位置，不要求等于校正记录里的历史快照；各次出现分别核
		// 对，已失效的出现同样核对。合并距离只是导入/校正时的接纳门槛，不
		// 是保存位置偏差的容许范围：重放中出现非有限结果或距离冲突，或最
		// 终平均位置与保存位置不完全一致，都按损坏拒绝。纯旧文件没有
		// sources、null 旧帧没有依据，均不重放。
		for _, lm := range fd.Landmarks {
			if len(lm.Occurrences) == 0 {
				// 旧版平铺路标即第 1 次出现。
				replay.seed(lm.ID, 1, lm.LegacyCount, lm.LegacyMX, lm.LegacyMY)
				continue
			}
			for _, oj := range lm.Occurrences {
				replay.seed(lm.ID, oj.Number, oj.LegacyCount, oj.LegacyMX, oj.LegacyMY)
			}
		}
		frames := make([]replayFrame, 0, len(fd.Sources))
		for k, src := range fd.Sources {
			if src == nil {
				continue // 旧地图帧：无逐帧依据，其贡献固定在旧贡献起点中
			}
			pose := fd.Trajectory[k+1]
			frames = append(frames, replayFrame{time: pose.Time, pose: pose, observations: src.Observations})
		}
		if rej := replay.replay(frames); rej != nil {
			switch rej.reason {
			case replayNonFinite:
				return fmt.Errorf("%w: replayed observation of landmark %s occurrence %d at frame time %d is non-finite", ErrCorrupt, rej.id, rej.num, rej.time)
			case replayConflict:
				return fmt.Errorf("%w: replayed observation of landmark %s occurrence %d at frame time %d violates merge distance", ErrCorrupt, rej.id, rej.num, rej.time)
			default:
				// 归属（存在性与时间边界）已在上面校验，不会无法归组。
				return fmt.Errorf("%w: observation of landmark %s at frame time %d belongs to no occurrence", ErrCorrupt, rej.id, rej.time)
			}
		}
		checkPosition := func(id string, num int, x, y float64) error {
			a := replay.agg(id, num)
			// 次数核对已保证 a.count 与记录次数一致（含旧贡献起点），这里只
			// 核对位置：保存位置必须与按依据重放出的等权平均完全一致。
			if a.x != x || a.y != y {
				return fmt.Errorf("%w: landmark %s occurrence %d is saved at (%v,%v) but its observations replay to (%v,%v)", ErrCorrupt, id, num, x, y, a.x, a.y)
			}
			return nil
		}
		for _, lm := range fd.Landmarks {
			if len(lm.Occurrences) == 0 {
				if err := checkPosition(lm.ID, 1, lm.X, lm.Y); err != nil {
					return err
				}
				continue
			}
			for _, oj := range lm.Occurrences {
				if err := checkPosition(lm.ID, oj.Number, oj.X, oj.Y); err != nil {
					return err
				}
			}
		}

		// “截至每一帧”的累计已接纳观测统计，供逐条校正记录按各自结束时间
		// 核对次数。同帧对同一标识的多条观测各计一次，无观测帧不增加；
		// null 旧帧没有逐帧观测，running 不增长——其贡献固定在该出现的
		// LegacyCount 中，使用时经 legacyByKey 另加，不能按零处理也不能
		// 按帧数推测。无法归组的观测在上面的归属校验中已被拒绝，这里跳过
		// 即可。只为校正结束帧所在下标复制快照（已在 cumBySrc 预登记），
		// 各快照相互独立，后续帧的增长不改写旧快照。
		running := make(map[occurrenceKey]int)
		for k, src := range fd.Sources {
			if src != nil {
				t := fd.Trajectory[k+1].Time
				for _, ob := range src.Observations {
					if num, known := replay.occurrenceOf(ob.ID, t); known && num != 0 {
						running[occurrenceKey{id: ob.ID, num: num}]++
					}
				}
			}
			if _, need := cumBySrc[k]; need {
				snap := make(map[occurrenceKey]int, len(running))
				for key, c := range running {
					snap[key] = c
				}
				cumBySrc[k] = snap
			}
		}
		// 各次出现保存的固定旧观测贡献次数（旧地图缺少逐帧依据的既有观
		// 测），作为所属出现的既有贡献计入截至记录结束时间的总数。
		legacyByKey = make(map[occurrenceKey]int, len(fd.Landmarks))
		for _, lm := range fd.Landmarks {
			if len(lm.Occurrences) == 0 {
				legacyByKey[occurrenceKey{id: lm.ID, num: 1}] = lm.LegacyCount
				continue
			}
			for _, oj := range lm.Occurrences {
				legacyByKey[occurrenceKey{id: lm.ID, num: oj.Number}] = oj.LegacyCount
			}
		}
	}
	segIDs := make(map[string]struct{}, len(fd.Segments))
	for _, sg := range fd.Segments {
		if sg.ID == "" || sg.Hash == "" {
			return fmt.Errorf("%w: invalid segment record", ErrCorrupt)
		}
		if _, dup := segIDs[sg.ID]; dup {
			return fmt.Errorf("%w: duplicate segment %s", ErrCorrupt, sg.ID)
		}
		segIDs[sg.ID] = struct{}{}
	}
	corrIDs := make(map[string]struct{}, len(fd.Corrections))
	for _, cr := range fd.Corrections {
		if cr.ID == "" || cr.Anchor > cr.EndTime {
			return fmt.Errorf("%w: invalid correction record", ErrCorrupt)
		}
		// 锚点与结束时间必须准确命中已导入帧：trajectory[0] 是初始位姿，
		// 不是可校正的帧，也不能用相邻帧的时间代替。轨迹时间已在前面
		// 校验为严格递增，命中即唯一。
		anchorIdx, endIdx := -1, -1
		for j := 1; j < len(fd.Trajectory); j++ {
			if fd.Trajectory[j].Time == cr.Anchor {
				anchorIdx = j
			}
			if fd.Trajectory[j].Time == cr.EndTime {
				endIdx = j
			}
		}
		if anchorIdx < 0 || endIdx < 0 {
			return fmt.Errorf("%w: correction %s range does not hit imported frames", ErrCorrupt, cr.ID)
		}
		// 记录必须恰好覆盖 [anchor, end] 内的每一帧：位姿条目数量等于
		// 范围内帧数，按轨迹时间次序一一对应，且同一份前后位姿的时间
		// 相同并就是对应帧的时间。缺失、重复、错序、额外加入范围外的
		// 帧，或把前后时间写成两个不同帧，都使记录不能完整描述声明的
		// 范围，按损坏拒绝。这里只核对覆盖的帧及时间：快照中的位置、
		// 朝向和方差是提交时的历史值，不要求等于当前轨迹（后来对相同
		// 范围再校正、或之后导入新帧，都不影响既有记录的合法性）。
		if len(cr.Poses) != endIdx-anchorIdx+1 {
			return fmt.Errorf("%w: correction %s does not cover every frame in its range", ErrCorrupt, cr.ID)
		}
		for i, pc := range cr.Poses {
			ft := fd.Trajectory[anchorIdx+i].Time
			if pc.Before.Time != ft || pc.After.Time != ft {
				return fmt.Errorf("%w: correction %s pose entry %d does not match frame time %d", ErrCorrupt, cr.ID, i, ft)
			}
			if !finitePose(pc.Before) || !finitePose(pc.After) {
				return fmt.Errorf("%w: correction %s has non-finite pose", ErrCorrupt, cr.ID)
			}
		}
		// 以下两项核对都只针对范围内逐帧依据完整的校正：范围内任一来源
		// 帧为 null 旧帧时保留旧文件的既有打开规则，不推测运动方差、也
		// 不把未知贡献当成零；纯旧文件缺省 sources（长度为 0，重放器不构
		// 建）时所有记录都不核对。同一文件的其余依据完整的记录不受含旧帧
		// 记录影响，仍逐一核对。
		fullyBased := len(fd.Sources) != 0
		if fullyBased {
			for k := anchorIdx - 1; k <= endIdx-1; k++ {
				if fd.Sources[k] == nil {
					fullyBased = false
					break
				}
			}
		}
		if fullyBased {
			// 校正后方差核对：锚点帧的校正后方差必须等于该次提交的目标
			// 方差；其后每帧在目标方差上，按时间顺序累加锚点之后至该帧
			// 的原运动方差。锚点自身进入该帧的运动方差不再加一次，也不
			// 能以校正前方差作为起点；累计范围以本记录自己的锚点与结束
			// 时间为准，后来对重叠范围的再校正与之后追加的帧都不属于本
			// 记录。目标方差或参与累计的运动方差为负/非有限、累计结果非
			// 有限，或与保存的校正后方差不完全一致，都按损坏拒绝整份文
			// 件——每一帧逐一核对，不能只凭锚点与末帧正确就接受中间错误
			// 的记录；目标方差与运动方差全为零的合法校正同样逐帧通过。
			accum := cr.Target.Variance
			if !isFinite(accum) || accum < 0 {
				return fmt.Errorf("%w: correction %s target variance is negative or non-finite", ErrCorrupt, cr.ID)
			}
			for i, pc := range cr.Poses {
				if i > 0 {
					// 记录内第 i 帧位于轨迹下标 anchorIdx+i；进入它的运
					// 动方差在来源 sources[anchorIdx+i-1]（i=1 即锚点之
					// 后第一帧），锚点自身的来源 sources[anchorIdx-1] 不
					// 参与累计。
					mv := fd.Sources[anchorIdx+i-1].MoveVariance
					if !isFinite(mv) || mv < 0 {
						return fmt.Errorf("%w: correction %s accumulates negative or non-finite motion variance at frame time %d", ErrCorrupt, cr.ID, pc.After.Time)
					}
					accum += mv
					if !isFinite(accum) {
						return fmt.Errorf("%w: correction %s corrected variance accumulates to non-finite value at frame time %d", ErrCorrupt, cr.ID, pc.After.Time)
					}
				}
				if pc.After.Variance != accum {
					return fmt.Errorf("%w: correction %s pose at frame time %d has corrected variance %v but target variance %v and the motion variances after the anchor accumulate to %v", ErrCorrupt, cr.ID, pc.After.Time, pc.After.Variance, cr.Target.Variance, accum)
				}
			}
			// 几何核对：整条记录必须描述同一次平移和旋转。只核对该记录
			// 自身保存的校正前后值与目标，不要求历史快照等于当前轨迹——
			// 后来对重叠范围再校正、或在结束时间之后追加轨迹，都不改写旧
			// 记录，也不能使原本合法的旧记录被拒绝。重定位规则与 Correct
			// 提交时共享同一实现（poseShift，见 correction.go）：旋转角、
			// 余弦正弦与期望位姿的运算次序完全一致，本包写出的合法记录重
			// 算出的期望值与保存值逐位相同；这里另按容差接纳浮点重算误
			// 差。锚点的校正后位置必须是目标位置、朝向必须是目标朝向归一
			// 到 [-π,π) 的结果；其余帧必须与锚点一起做同一次刚体重定
			// 位：保留校正前相对锚点的位置关系与朝向差。每一帧都逐一核
			// 对——只有锚点与末帧正确而中间一帧位置偏离或单独转向，同样
			// 按损坏拒绝；范围只有锚点一帧时本核对即只针对该帧。坐标容差
			// 为 1e-9 乘以 1、期望值绝对值、保存值绝对值三者的最大值；
			// 朝向按最短角度差比较，容差 1e-9 弧度。容差与路标合并距离无
			// 关：合并距离只是导入/校正时的观测接纳门槛，不能用来放过记
			// 录内部的几何矛盾。目标位置/朝向与锚点校正前完全相同（角度
			// 等价）时是恒等（只调方差）校正，期望几何直接取校正前值，与
			// Correct 的同一分支保持一致：横跨 ±1e308 的轨迹上“相对锚
			// 点偏移”会溢出，不能因此把合法的恒等校正误判为损坏。
			anchorBefore := cr.Poses[0].Before
			shift := newPoseShift(cr.Target, anchorBefore)
			for i, pc := range cr.Poses {
				var wantX, wantY, wantHeading float64
				if i == 0 {
					wantX, wantY, wantHeading = shift.x, shift.y, shift.heading
				} else {
					wantX, wantY, wantHeading = shift.apply(pc.Before)
				}
				if !coordClose(pc.After.X, wantX) {
					return fmt.Errorf("%w: correction %s pose at frame time %d has corrected x %v but the record's target and pre-correction poses rigidly move it to %v", ErrCorrupt, cr.ID, pc.After.Time, pc.After.X, wantX)
				}
				if !coordClose(pc.After.Y, wantY) {
					return fmt.Errorf("%w: correction %s pose at frame time %d has corrected y %v but the record's target and pre-correction poses rigidly move it to %v", ErrCorrupt, cr.ID, pc.After.Time, pc.After.Y, wantY)
				}
				if !angleClose(pc.After.Heading, wantHeading) {
					return fmt.Errorf("%w: correction %s pose at frame time %d has corrected heading %v but the record's rotation makes it %v", ErrCorrupt, cr.ID, pc.After.Time, pc.After.Heading, wantHeading)
				}
			}
		}
		for _, lc := range cr.Landmarks {
			if lc.ID == "" {
				return fmt.Errorf("%w: correction %s has empty landmark id", ErrCorrupt, cr.ID)
			}
			if lc.Occurrence < 0 || !isFinite(lc.Before.X) || !isFinite(lc.Before.Y) ||
				!isFinite(lc.After.X) || !isFinite(lc.After.Y) ||
				lc.Before.Count < 1 || lc.After.Count < 1 {
				return fmt.Errorf("%w: correction %s has invalid landmark change", ErrCorrupt, cr.ID)
			}
		}
		// 路标列表必须恰好描述记录范围（锚点帧到结束帧，两端包含；之后
		// 追加的帧不属于范围）内逐帧观测实际涉及的路标出现：范围内被观测
		// 到的每个（路标，出现编号）必须恰好有一条前后记录，同一次出现被
		// 多帧或同帧多条观测涉及也只记一条；少记、多记、重复、或把出现
		// 编号改指该范围没有涉及的另一出现，都按损坏拒绝整份文件，而不是
		// 只看条目里的坐标与次数是否合法。归组沿用与回环校正相同的时间边
		// 界规则（重放器，见 replay.go）：同一标识失效后再现属于不同出现，
		// 即使位置相同也分别对应；已失效的旧出现只要范围内（含失效时刻）
		// 有它的观测就必须在列表中，不因当前区域查询不再返回它而被排除；
		// 范围外帧（如记录之后才再现的新出现）的观测不计入。范围内没有
		// 任何路标观测时列表必须为空，非空即损坏。仅对范围内逐帧依据完整
		// 的校正做此核对：范围内含 null 旧帧的校正缺少逐帧依据，保留旧地
		// 图的既有打开规则，不凭推测要求补造观测。
		if replay != nil && fullyBased {
			rangeFrames := make([]replayFrame, 0, endIdx-anchorIdx+1)
			for j := anchorIdx; j <= endIdx; j++ {
				rangeFrames = append(rangeFrames, replayFrame{time: fd.Trajectory[j].Time, observations: fd.Sources[j-1].Observations})
			}
			want := replay.observed(rangeFrames)
			got := make(map[occurrenceKey]struct{}, len(cr.Landmarks))
			for _, lc := range cr.Landmarks {
				num := lc.Occurrence
				if num == 0 {
					num = 1 // 更早版本写出的校正记录不带编号，按第 1 次出现解释
				}
				if num < 1 || num > replay.occurrences(lc.ID) {
					return fmt.Errorf("%w: correction %s lists landmark %s occurrence %d not touched by its range", ErrCorrupt, cr.ID, lc.ID, num)
				}
				key := occurrenceKey{id: lc.ID, num: num}
				if _, dup := got[key]; dup {
					return fmt.Errorf("%w: correction %s lists landmark %s occurrence %d more than once", ErrCorrupt, cr.ID, lc.ID, num)
				}
				got[key] = struct{}{}
			}
			for key := range want {
				if _, ok := got[key]; !ok {
					return fmt.Errorf("%w: correction %s misses landmark %s occurrence %d observed in its range", ErrCorrupt, cr.ID, key.id, key.num)
				}
			}
			for key := range got {
				if _, ok := want[key]; !ok {
					return fmt.Errorf("%w: correction %s lists landmark %s occurrence %d with no observation in its range", ErrCorrupt, cr.ID, key.id, key.num)
				}
			}

			// 观测次数核对：回环校正只移动轨迹、不增删已接受观测，因此对
			// 于依据完整的记录，其每个受影响路标出现的校正前、校正后次数
			// 都必须等于截至“本记录结束时间”已经接纳、归属该次出现的观
			// 测总数。这个总数按各记录自己的结束帧从累计快照截取：包含锚
			// 点之前属于同一次出现的观测与结束帧上的观测，不只是被移动的
			// [anchor,end] 那段；同帧多条观测各计一次，无观测帧不增加；
			// 该出现保存的固定旧观测贡献（旧地图既有观测）也要计入，不能
			// 当作零。结束帧之后才接纳的观测（例如记录结束于 300、后来在
			// 400 又观测一次）不属于本记录；后来对重叠范围的再次校正不改
			// 变判断——每条记录都以自己的结束时间为准。各次出现分别核
			// 对，不能借另一出现的观测补足；已失效的旧出现只要被该条校正
			// 涉及同样核对。校正前或校正后任一次数不符，即使路标列表、位
			// 置与文件校验都正常，也按损坏拒绝整份地图。省略出现编号的旧
			// 条目沿用按第 1 次出现解释的规则。范围内含 null 旧帧时依据不
			// 完整，保留旧文件的既有打开规则（fullyBased 为假，不到此）。
			snapshot := cumBySrc[endIdx-1]
			for _, lc := range cr.Landmarks {
				num := lc.Occurrence
				if num == 0 {
					num = 1
				}
				wantCount := snapshot[occurrenceKey{id: lc.ID, num: num}] + legacyByKey[occurrenceKey{id: lc.ID, num: num}]
				if lc.Before.Count != wantCount {
					return fmt.Errorf("%w: correction %s landmark %s occurrence %d records %d pre-correction observations but %d were accepted by its end time %d", ErrCorrupt, cr.ID, lc.ID, num, lc.Before.Count, wantCount, cr.EndTime)
				}
				if lc.After.Count != wantCount {
					return fmt.Errorf("%w: correction %s landmark %s occurrence %d records %d post-correction observations but %d were accepted by its end time %d", ErrCorrupt, cr.ID, lc.ID, num, lc.After.Count, wantCount, cr.EndTime)
				}
			}
		}
		if _, dup := corrIDs[cr.ID]; dup {
			return fmt.Errorf("%w: duplicate correction %s", ErrCorrupt, cr.ID)
		}
		corrIDs[cr.ID] = struct{}{}
	}
	// 路标记录按标识索引，供失效记录与出现历史的交叉核对使用。
	lmByID := make(map[string]*landmarkJSON, len(fd.Landmarks))
	for i := range fd.Landmarks {
		lmByID[fd.Landmarks[i].ID] = &fd.Landmarks[i]
	}
	invalIDs := make(map[string]struct{}, len(fd.Invalidations))
	// invalTriples 记录每条失效操作实际引用的（操作标识，路标，出现编号）
	// 三元组，供反向核对：每个已失效出现都必须是某条操作记录里的实际条目。
	type invalTriple struct {
		op  string
		lm  string
		num int
	}
	invalTriples := make(map[invalTriple]struct{}, len(fd.Invalidations))
	for _, iv := range fd.Invalidations {
		if iv.ID == "" || iv.Reason == "" || iv.Hash == "" || len(iv.Landmarks) == 0 {
			return fmt.Errorf("%w: invalid invalidation record", ErrCorrupt)
		}
		if _, dup := invalIDs[iv.ID]; dup {
			return fmt.Errorf("%w: duplicate invalidation %s", ErrCorrupt, iv.ID)
		}
		invalIDs[iv.ID] = struct{}{}
		lmSeen := make(map[string]struct{}, len(iv.Landmarks))
		for _, l := range iv.Landmarks {
			if l.ID == "" || l.Occurrence < 1 {
				return fmt.Errorf("%w: invalid invalidation landmark entry", ErrCorrupt)
			}
			if _, dup := lmSeen[l.ID]; dup {
				return fmt.Errorf("%w: invalidation %s lists %s twice", ErrCorrupt, iv.ID, l.ID)
			}
			lmSeen[l.ID] = struct{}{}
		}
		// 交叉核对：成功失效结果里的每个（路标标识，出现编号）必须准确
		// 指向该路标历史中同编号的那次出现，不能改指同一路标的其他出现，
		// 也不能因为路标后来再次出现就把旧结果指向最新记录。被指出现必须
		// 已经失效，且其上记录的失效操作标识、失效时间、失效原因都与这条
		// 操作记录一致——时间与原因各自再合理也不够，实际由另一条操作撤下
		// 时不能仅凭相同时间/原因认可。旧版平铺路标视为第 1 次有效出现，
		// 不可能被失效记录引用（引用即损坏）。一条操作同时撤下多个路标时，
		// 任意一个条目不满足对应关系都拒绝打开整个文件。
		for _, l := range iv.Landmarks {
			lm := lmByID[l.ID]
			if lm == nil {
				return fmt.Errorf("%w: invalidation %s result points to unknown landmark %s", ErrCorrupt, iv.ID, l.ID)
			}
			if len(lm.Occurrences) == 0 {
				return fmt.Errorf("%w: invalidation %s result points to flat legacy landmark %s which has no invalidated occurrence", ErrCorrupt, iv.ID, l.ID)
			}
			if l.Occurrence > len(lm.Occurrences) {
				return fmt.Errorf("%w: invalidation %s result points to landmark %s occurrence %d which does not exist", ErrCorrupt, iv.ID, l.ID, l.Occurrence)
			}
			// 出现编号连续性已在上方路标校验中强制，该下标处编号即 l.Occurrence。
			oj := lm.Occurrences[l.Occurrence-1]
			if oj.Active {
				return fmt.Errorf("%w: invalidation %s result points to landmark %s occurrence %d which is still active", ErrCorrupt, iv.ID, l.ID, l.Occurrence)
			}
			if oj.InvalidOpID != iv.ID || oj.InvalidTime != iv.Time || oj.InvalidReason != iv.Reason {
				return fmt.Errorf("%w: invalidation %s result for landmark %s occurrence %d does not match its saved invalidation (op %q, time %d, reason %q)", ErrCorrupt, iv.ID, l.ID, l.Occurrence, oj.InvalidOpID, oj.InvalidTime, oj.InvalidReason)
			}
			invalTriples[invalTriple{op: iv.ID, lm: l.ID, num: l.Occurrence}] = struct{}{}
		}
	}
	// 反向核对：每个已失效出现都必须能在失效操作序列中找到引用同一（操作，
	// 路标，出现编号）三元组的条目。正向核对已保证被引用出现的失效时间与
	// 原因和引用方一致；此处堵住另一方向的矛盾：出现凭空携带失效信息、
	// 声称撤下它的操作记录实际指向另一次出现，或两次出现声称被同一操作
	// 撤下（一次操作对同一路标只会撤下当时唯一的有效出现）。旧地图没有
	// 失效操作时，平铺路标视为有效、不携带失效信息，不会触发；旧地图后来
	// 产生的失效操作同样在上述核对之列，不要求补齐原本缺失的逐帧观测。
	for _, lm := range fd.Landmarks {
		for _, oj := range lm.Occurrences {
			if oj.Active {
				continue
			}
			if _, ok := invalTriples[invalTriple{op: oj.InvalidOpID, lm: lm.ID, num: oj.Number}]; !ok {
				return fmt.Errorf("%w: landmark %s occurrence %d is marked invalidated by operation %q which does not record that invalidation", ErrCorrupt, lm.ID, oj.Number, oj.InvalidOpID)
			}
		}
	}
	return nil
}

func finitePose(p Pose) bool {
	return isFinite(p.X) && isFinite(p.Y) && isFinite(p.Heading) && isFinite(p.Variance)
}

// geomTol 是打开时核对校正记录几何一致性的相对容差（另含 1 的绝对项）。
const geomTol = 1e-9

// coordClose 判断保存坐标 got 是否在容许误差内等于期望 want：误差不得
// 超过 geomTol 乘以 1、|want|、|got| 三者中的最大值。参与比较的值都已
// 校验为有限，差值必有限，NaN 不会混入并被误当相等。
func coordClose(got, want float64) bool {
	scale := math.Max(1, math.Max(math.Abs(want), math.Abs(got)))
	return math.Abs(got-want) <= geomTol*scale
}

// angleClose 按最短角度差判断两个角度是否相等，容差 geomTol 弧度。两个
// 角度都已校验为有限；差值经归一化到 [-π,π) 即最短角度差，正确处理
// ±π 附近跨边界但物理方向相同的情形。
func angleClose(got, want float64) bool {
	return math.Abs(normalizeAngle(got-want)) <= geomTol
}

// canonicalCorrectionHash 计算一次校正请求（锚点时间 + 目标位姿）的
// 确定性指纹，用于同标识重复提交判定。直接按 IEEE-754 位编码。
func canonicalCorrectionHash(anchor int64, tgt CorrectionTarget) string {
	h := sha256.New()
	var b [8]byte
	binary.BigEndian.PutUint64(b[:], uint64(anchor))
	h.Write(b[:])
	for _, v := range []float64{tgt.X, tgt.Y, tgt.Heading, tgt.Variance} {
		binary.BigEndian.PutUint64(b[:], math.Float64bits(v))
		h.Write(b[:])
	}
	return fmt.Sprintf("%x", h.Sum(nil))
}

// saveExclusive 创建新文件，目标已存在即失败（O_EXCL）。
func (m *Map) saveExclusive() error {
	data, err := encodeFile(m.state)
	if err != nil {
		return err
	}
	f, err := os.OpenFile(m.path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
	if err != nil {
		return err
	}
	return writeAndClose(f, data, m.path)
}

// saveReplace 用同目录临时文件 + rename 原子替换现有文件。
func (m *Map) saveReplace() (err error) {
	data, err := encodeFile(m.state)
	if err != nil {
		return err
	}
	dir, base := filepath.Split(m.path)
	if dir == "" {
		dir = "."
	}
	f, err := os.CreateTemp(dir, base+".tmp-*")
	if err != nil {
		return err
	}
	tmpName := f.Name()
	// 任何失败路径都尽力清理临时文件。
	defer func() {
		if err != nil {
			_ = os.Remove(tmpName)
		}
	}()
	if err = writeAndClose(f, data, tmpName); err != nil {
		return err
	}
	if err = os.Rename(tmpName, m.path); err != nil {
		return err
	}
	return nil
}

func writeAndClose(f *os.File, data []byte, name string) (err error) {
	defer func() {
		if cerr := f.Close(); err == nil {
			err = cerr
		}
	}()
	if _, err = f.Write(data); err != nil {
		return err
	}
	if err = f.Sync(); err != nil {
		return err
	}
	return nil
}

// canonicalHash 计算一批帧的确定性指纹，用于重复导入判定。直接按
// IEEE-754 位编码，NaN/Inf 也有稳定表示，不依赖 JSON 对其不支持的问题。
func canonicalHash(frames []Frame) string {
	h := sha256.New()
	var lenBuf [4]byte
	var numBuf [8]byte
	putU32 := func(v uint32) {
		binary.BigEndian.PutUint32(lenBuf[:], v)
		h.Write(lenBuf[:])
	}
	putU64 := func(v uint64) {
		binary.BigEndian.PutUint64(numBuf[:], v)
		h.Write(numBuf[:])
	}
	putStr := func(s string) {
		putU32(uint32(len(s)))
		h.Write([]byte(s))
	}

	putU32(uint32(len(frames)))
	for _, fr := range frames {
		putU64(uint64(fr.Time))
		putU64(math.Float64bits(fr.DX))
		putU64(math.Float64bits(fr.DY))
		putU64(math.Float64bits(fr.DHeading))
		putU64(math.Float64bits(fr.MoveVariance))
		putU32(uint32(len(fr.Observations)))
		for _, ob := range fr.Observations {
			putStr(ob.ID)
			putU64(math.Float64bits(ob.X))
			putU64(math.Float64bits(ob.Y))
		}
	}
	return fmt.Sprintf("%x", h.Sum(nil))
}

