	h, err := m2.LandmarkAppearances("L")
	if err != nil {
		t.Fatal(err)
	}
	if len(h.Appearances) != 1 || !h.Appearances[0].HasFirstSeen || h.Appearances[0].FirstSeenTime != 100 ||
		h.Appearances[0].Landmark.Count != 2 {
		t.Fatalf("appearances = %+v", h.Appearances)
	}
}

