224			t.Fatalf("open legacy: %v", err)
225		}
226		// 旧地图上追加带来源的新帧：t=300 观测 K（旧路标无起始边界，接受）。
227		if _, err := m2.ImportSegment(Segment{ID: "new", Frames: []Frame{
